macro.command:
// ============================================================
// 百变腕甲  Protean Vambrace — 物品宏 [postActiveEffects]
// 在 Foundry 内开出妄质拉霸面板；停盘后将官方效果文字发为聊天卡。
// 自动档（已坐实）：治疗(applyDamage healing)、污染层数计数(flag)。
// 其余档先发卡，由 PL/DM 执行；后续阶段逐档接 completeActivityUse / DAE。
// ============================================================
(async () => {
  const actor = (typeof item!=="undefined" && item?.actor) ? item.actor
              : (typeof token!=="undefined" && token?.actor) ? token.actor
              : game.user?.character;
  if (!actor) { ui.notifications.warn("百变腕甲：找不到持有者角色。"); return; }

  // —— 递归守卫：completeActivityUse 触发的子活动会重跑本宏；面板已开 / 非「拉杆」活动 → 直接返回（伤害由 midi 正常结算）——
  try{ const __an=(typeof workflow!=="undefined"&&workflow?.activity?.name)?workflow.activity.name:""; if(__an && !__an.includes("拉杆")) return; }catch(e){}
  if(globalThis.__pvPanelOpen){ return; }

  // ---------- 数据：与原型一致 ----------
  const ORDER=['fire','frost','overload','arcane','delirium','seven'];
  const NAME={fire:'烈焰',frost:'寒霜',overload:'过载',arcane:'奥能',delirium:'妄质',seven:'七'};
  const COMMONS=['fire','frost','overload','arcane','delirium'];
  const TIERW=[['grand',4],['jackpot',16],['pair',31],['consol',49]];
  const ri=n=>Math.floor(Math.random()*n);
  const shuffle=a=>{for(let i=a.length-1;i>0;i--){const j=ri(i+1);[a[i],a[j]]=[a[j],a[i]];}return a;};
  function rollTier(){let x=Math.random()*100;for(const[t,w]of TIERW){if(x<w)return t;x-=w;}return 'consol';}
  function buildResult(){
    const tier=rollTier();
    if(tier==='grand')   return {res3:['seven','seven','seven'], r:{tier:'grand'}};
    if(tier==='jackpot'){const s=COMMONS[ri(COMMONS.length)];return {res3:[s,s,s], r:{tier:'jackpot',sym:s}};}
    if(tier==='pair'){const s=COMMONS[ri(COMMONS.length)];let o;do{o=COMMONS[ri(COMMONS.length)];}while(o===s);
      return {res3:shuffle([s,s,o]), r:{tier:'pair',sym:s}};}
    return {res3:shuffle(COMMONS.slice()).slice(0,3), r:{tier:'none'}};
  }
  const SVG={
    fire:'<svg viewBox="0 0 32 32" fill="none" stroke="#ff6a3a" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M16 3c4 5 .5 8 1 11 .4-1.4 1.6-2.4 2.6-3 .2 1.8-.4 3 .8 4.6 1.4 1.8 2.6 3.4 2.6 6.4a8 8 0 0 1-16 0c0-3 1.4-5 3-7 .2 1.4 1 2.4 2 3-1.2-4-1-9.6 4-15z"/></svg>',
    frost:'<svg viewBox="0 0 32 32" fill="none" stroke="#54e6ff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 3v26M5 9l22 14M27 9L5 23"/><path d="M16 7l-3 3M16 7l3 3M16 25l-3-3M16 25l3-3M8 12l.5 4.2M24 12l-.5 4.2M8 20l.5-4M24 20l-.5-4"/></svg>',
    overload:'<svg viewBox="0 0 32 32" fill="#ffd23a" stroke="#ffd23a" stroke-width="1.2" stroke-linejoin="round"><path d="M18 2 7 18h7l-3 12 13-17h-7l3-11z"/></svg>',
    arcane:'<svg viewBox="0 0 32 32" fill="#7db0ff"><path d="M16 2c1.4 7 5 10.6 12 14-7 3.4-10.6 7-12 14-1.4-7-5-10.6-12-14C11 12.6 14.6 9 16 2z"/><circle cx="6" cy="8" r="1.7"/><circle cx="26" cy="24" r="1.7"/></svg>',
    delirium:'<svg viewBox="0 0 32 32" fill="none" stroke="#c44dff" stroke-width="2.2" stroke-linejoin="round"><path d="M16 2 6 12l4 18h12l4-18L16 2z"/><path d="M16 2v28M6 12h20M11 12l3 18M21 12l-3 18"/></svg>',
    seven:'<span class="pv-seven">7</span>'
  };

  // ---------- 效果文字（纯正5E措辞，与定稿一致）----------
  const GRAND='【★ 777 ★】在本回合，你施放的每个法术都以你可使用的最高法术环阶施放，且这些法术的所有伤害骰均取最大值（由 DM 裁定）。';
  const JACKPOT={
    fire:'【熔流喷发】以 60 尺内你能看见的一点为中心、半径 25 尺范围内，每个生物须进行一次敏捷豁免。失败者受到 12d6 点火焰伤害，成功者受到一半伤害。',
    frost:'【绝对零度】60 尺内至多 3 个你能看见的生物须各进行一次体质豁免。失败者陷入无法行动状态，直到你的下一回合结束。',
    overload:'【超频】在本回合，你施放的法术的所有伤害骰均取最大值（由 DM 裁定）。',
    arcane:'【奥能返还】你立即恢复一个已消耗的法术位，其环阶至多为 5 环。'};
  const SURGE=[
    '【妄质冲击】以 60 尺内你能看见的一点为中心、半径 20 尺范围内，每个生物须进行一次敏捷豁免。失败者受到 8d8 点暗蚀伤害，并被从该点向外推开 15 尺；成功者受到一半伤害，且不被推开。你的污染层数 +1。',
    '【混沌闪现】你传送至 60 尺内一处你能看见的未被占据的空间；在你目的地周围 15 尺内，每个敌人须进行一次敏捷豁免，失败者受到 6d6 点力场伤害，成功者受到一半伤害。你的污染层数 +1。',
    '【连环戏法】在本回合，你可以立即免费施放一个你已知的戏法三次，每次可分别选择目标。你的污染层数 +1。',
    '【妄质护壳】你获得 40 点临时生命值，并获得对一切伤害的抗性，直到你的下一回合开始。你的污染层数 +1。',
    '【超载狂欢】在本回合，你获得一个额外的动作和一个额外的移动动作，且你施放的下一个法术的所有伤害骰取最大值（由 DM 裁定）。你的污染层数 +1。',
    '【妄质回火】你受到 2d6 点暗蚀伤害。你的污染层数 +1。'];
  const PAIR={
    fire:'【烈焰】在本回合，你施放的每个法术的伤害增加 2d6 点火焰伤害。',
    frost:'【寒霜】60 尺内你能看见的一个生物，其速度减半，且针对它的下一次攻击检定具有优势，直到你的下一回合开始。',
    overload:'【过载】在本回合，你的法术攻击检定具有优势。',
    arcane:'【奥能】在本回合，你的法术豁免 DC 增加 2。',
    delirium:'【奥术异常】在本回合，你施放的每个法术的伤害增加 2d6 点暗蚀伤害；此外立即引动一次狂野魔法浪涌（由 DM 投掷并裁定）。你的污染层数 +1。'};
  const CONSOL=[
    '你获得 5 点临时生命值。',
    '60 尺内你能看见的一个生物，一道奥术飞弹射向它，造成 2d8 点力场伤害。',
    '你的下一次豁免检定获得 +2 加值。',
    '你施放的下一个戏法额外造成 1d8 点伤害，其类型与该戏法相同。',
    '你的速度增加 10 尺，直到你当前回合结束。',
    '你的下一次攻击检定（包括法术攻击检定）具有优势。',
    '你恢复 1d8 点生命值。',
    '你可以立即移动至多 10 尺，此移动不会引发借机攻击。',
    '【微光环】一圈柔光环绕你身，直到你的下一回合开始；其间与你相距 10 尺内的友方生物的 AC 获得 +1 加值。',
    '【回火】你受到 1d4 点力场伤害。',
    '在本回合，你施放的法术的豁免 DC 提升 1。',
    '在本回合，你的法术攻击检定获得 +2 加值。',
    '你获得对火焰伤害与力场伤害的抗性，直到你的下一回合开始。',
    '你立即结束一个正在影响你的状态（由你选择）。',
    '在本回合，你的近战攻击触及增加 5 尺。',
    '你向 60 尺内一个你能看见的生物释放一道心灵冲击：它受到 1d4 点心灵伤害，并须进行一次体质豁免，失败则倒地。',
    '你能看见的 60 尺内一个生物的速度降低 10 尺，直到它的下一回合结束。',
    '你扰乱 60 尺内一个你能看见的生物：它的下一次攻击检定具有劣势。',
    '你能看见的 60 尺内一个生物须进行一次力量豁免，失败则被自你推开 10 尺。',
    '你能看见的 60 尺内一个生物须进行一次体质豁免，失败则目盲，直到它的下一回合结束。',
    '你的下一次豁免检定具有劣势。',
    '你的装束泛起妄质流光，在你周身投下 10 尺半径的微光光照，直到你当前回合结束。',
    '你显化一只奥术之手（如同《法师之手》戏法），可操控 30 尺内一个不超过 5 磅的物件，持续到你当前回合结束。',
    '你在 60 尺内一个你能看见的生物脚下凝出寒冰：它须进行一次敏捷豁免，失败则倒地。',
    '你复现你最近施放过的一个戏法，立即再次免费施放它一次（可重新选择目标）。'];

  // 返回 {text, kind, n} —— kind 用于自动派发
  function outcome(r){
    if(r.tier==='grand') return {text:GRAND, kind:'grand'};
    if(r.tier==='jackpot'){
      if(r.sym==='delirium'){const n=ri(6);return {text:`(1d6=${n+1}) ${SURGE[n]}`, kind:'surge', n};}
      return {text:JACKPOT[r.sym], kind:'jackpot_'+r.sym};
    }
    if(r.tier==='pair') return {text:PAIR[r.sym], kind:'pair_'+r.sym};
    const n=ri(CONSOL.length); return {text:CONSOL[n], kind:'consol', n};
  }

  // ---------- 自动派发：坐实可自动的档位 ----------
  const PVIMG="icons/equipment/wrist/bracer-armored-steel-purple.webp";
  const ITEMUUID=(typeof item!=="undefined"&&item)?item.uuid:null;
  async function mkEff(name,changes,desc,icon,spec,extra){
    await actor.createEmbeddedDocuments("ActiveEffect",[Object.assign({
      name, img:icon||PVIMG, changes, duration:{rounds:1}, disabled:false, transfer:false, origin:ITEMUUID,
      description:desc, statuses:[], flags:{dae:{disableIncapacitated:false,selfTarget:false,selfTargetAlways:false,dontApply:false,stackable:"noneName",showIcon:true,durationExpression:"",macroRepeat:"none",specialDuration:(spec||[])}}
    }, extra||{})]);
  }
  // 用名称匹配本物品上的隐藏活动并触发（对敌伤害/状态档）
  function findAct(needle){
    let a=null;
    try{ a=item.system.activities.find?.(x=>x?.name&&x.name.includes(needle)); }catch(e){}
    if(!a){ try{ for(const x of item.system.activities){ if(x?.name&&x.name.includes(needle)){a=x;break;} } }catch(e){} }
    return a;
  }
  // 触发本物品的隐藏活动：AoE 弹出放模板；choice:true 的活动弹出「选择目标」。返回 {ok,wf}
  async function useAct(needle){
    const act=findAct(needle);
    if(!act){ ui.notifications.warn(`百变腕甲：未找到活动「${needle}」。`); return {ok:false}; }
    try{ const wf=await MidiQOL.completeActivityUse(act,{},{},{}); return {ok:true,wf}; }
    catch(e){ console.error("百变腕甲 useAct",e); return {ok:false}; }
  }
  // 击退失败者（背离爆心 distFt 尺）—— midi 原生，玩家端可用，不依赖世界脚本
  async function knockbackFailed(wf, distFt){
    try{
      const failed = wf?.failedSaves ? Array.from(wf.failedSaves) : [];
      if(!failed.length) return "（无失败目标，未击退）";
      let center=null;
      try{ const tuuid=wf.templateUuid||wf.template?.uuid; if(tuuid){ const td=await fromUuid(tuuid); center=(Number.isFinite(td?.x)?{x:td.x,y:td.y}:td?.object?.center)||null; } }catch(e){}
      if(!center && wf?.template && Number.isFinite(wf.template.x)) center={x:wf.template.x,y:wf.template.y};
      if(!center){ const me=(actor.getActiveTokens&&actor.getActiveTokens()[0])||(typeof token!=="undefined"?token:null); center=me?.center||null; }
      if(!center) return "失败者击退请手动处理（未取得爆心）。";
      if(typeof MidiQOL.moveTokenAwayFromPoint!=="function") return "失败者击退请手动处理（midi 无 moveTokenAwayFromPoint）。";
      let n=0;
      for(const tt of failed){ const tk=tt.object||tt; try{ await MidiQOL.moveTokenAwayFromPoint(tk, distFt, center, true, true); n++; }catch(e){ console.error("百变腕甲 push one",e); } }
      return `已将 ${n} 个失败目标自爆心击退 ${distFt} 尺。`;
    }catch(e){ console.error("百变腕甲 knockback",e); return "（击退异常，请手动击退）"; }
  }
  // 污染层数：不再自动统计，仅提示（由龙华自行记录）
  function pollute(extra){ return (extra?extra+" ":"")+"污染层数 +1（请自行记录）。"; }
  async function autoApply(o){
    // ===== 777 大头奖 =====
    if(o.kind==='grand'){
      await mkEff("七运当头  Lucky Seven",[],"在本回合，你施放的每个法术都以你可使用的最高法术环阶施放，且其所有伤害骰均取最大值。","icons/magic/light/beam-explosion-pink-purple.webp");
      return "已挂载提醒效应（最高环阶 + 伤害取最大值）；伤害最大化由 DM 裁定（掷伤害时取最大值）。";
    }
    // ===== 小奖 =====
    if(o.kind==='pair_fire'){ await mkEff("烈焰  Blaze",[{key:"system.bonuses.spell.damage",mode:2,value:"2d6[fire]",priority:20}],"在本回合，你施放的每个法术的伤害增加 2d6 点火焰伤害。","icons/magic/fire/blast-jet-stream-embers-red.webp"); return "已挂载：本回合法术伤害 +2d6 火焰。"; }
    if(o.kind==='pair_overload'){ await mkEff("过载  Overload",[{key:"flags.midi-qol.advantage.attack.msak",mode:2,value:"1",priority:20},{key:"flags.midi-qol.advantage.attack.rsak",mode:2,value:"1",priority:20}],"在本回合，你的法术攻击检定具有优势。","icons/magic/lightning/bolt-blue.webp"); return "已挂载：本回合法术攻击优势。"; }
    if(o.kind==='pair_arcane'){ await mkEff("奥能  Arcana",[{key:"system.bonuses.spell.dc",mode:2,value:"2",priority:20}],"在本回合，你的法术豁免 DC 增加 2。","icons/magic/symbols/rune-sigil-green-purple.webp"); return "已挂载：本回合法术 DC +2。"; }
    if(o.kind==='pair_frost'){ const a=await useAct("寒霜"); return a.ok?"已发动「寒霜」：点选一个目标，使其速度减半且你对它的下次攻击具有优势。":"⚠ 寒霜触发失败，请手动结算。"; }
    if(o.kind==='pair_delirium'){ await mkEff("奥术异常  Arcane Anomaly",[{key:"system.bonuses.spell.damage",mode:2,value:"2d6[necrotic]",priority:20}],"在本回合，你施放的每个法术的伤害增加 2d6 点暗蚀伤害。","icons/magic/death/hand-undead-skeleton-fire-pink.webp"); return `已挂载：本回合法术伤害 +2d6 暗蚀。${pollute("")} 另请 DM 投掷 1d700 引动狂野魔法浪涌。`; }
    // ===== 大奖三连 =====
    if(o.kind==='jackpot_fire'){ const a=await useAct("熔流喷发"); return a.ok?"已发动「熔流喷发」：放置 25 尺法球后自动结算敏捷豁免与火焰伤害。":"⚠ 熔流喷发触发失败，请手动结算。"; }
    if(o.kind==='jackpot_frost'){ const a=await useAct("绝对零度"); return a.ok?"已发动「绝对零度」：点选至多 3 个目标后自动结算体质豁免；失败者被冻结。":"⚠ 绝对零度触发失败，请手动结算。"; }
    if(o.kind==='jackpot_overload'){ await mkEff("超频  Surge State",[],"在本回合，你施放的法术的所有伤害骰均取最大值。","icons/magic/lightning/bolt-beam-strike-blue.webp"); return "已挂载提醒：本回合法术伤害取最大值（由 DM 裁定，掷伤害时取最大值）。"; }
    if(o.kind==='jackpot_arcane'){
      const sp=actor.system.spells||{}; let best=null;
      for(let l=5;l>=1;l--){ const x=sp["spell"+l]; if(x&&Number(x.value)<Number(x.max)){best=l;break;} }
      if(best){ await actor.update({["system.spells.spell"+best+".value"]: Number(sp["spell"+best].value)+1}); return `已恢复一个 ${best} 环法术位。`; }
      return "未找到可恢复的法术位（≤5 环均已满或无）。";
    }
    // ===== 妄质狂涌（1d6 子表）=====
    if(o.kind==='surge'){
      if(o.n===0){ const a=await useAct("妄质冲击"); let kb=a.ok&&a.wf?(" "+await knockbackFailed(a.wf,15)):" 失败者击退 15 尺请手动处理。"; return `已发动「妄质冲击」：放置 20 尺法球后结算敏捷豁免与暗蚀伤害。${kb} ${pollute("")}`; }
      if(o.n===1){ const a=await useAct("混沌闪现"); return `${a.ok?"已发动「混沌闪现」：在落点放置 15 尺法球后结算敏捷豁免与力场伤害。":"⚠ 混沌闪现触发失败，请手动结算。"} 你另传送至 60 尺内可见空位（由你手动移动 token）。 ${pollute("")}`; }
      if(o.n===2){ await mkEff("连环戏法  Cantrip Cascade",[],"在本回合，你可以立即免费施放一个你已知的戏法三次，每次可分别选择目标。","icons/magic/symbols/rune-sigil-green.webp"); return `已挂载提醒：免费施放一个戏法三次（由你执行）。 ${pollute("")}`; }
      if(o.n===3){
        let t=""; if(typeof actor.applyTempHP==="function"){ await actor.applyTempHP(40); t="已获得 40 点临时生命值。"; } else { t="请手动获得 40 点临时生命值。"; }
        await mkEff("妄质护壳  Delirium Carapace",[],"你获得对一切伤害的抗性，直到你的下一回合开始。","icons/magic/defensive/shield-barrier-flaming-diamond-blue-yellow.webp");
        return `${t} 已挂载抗性提醒（对一切伤害抗性，至你下回合；若系统未自动减半请手动）。 ${pollute("")}`;
      }
      if(o.n===4){ await mkEff("超载狂欢  Overload Frenzy",[],"在本回合，你获得一个额外的动作和一个额外的移动动作，且你施放的下一个法术的所有伤害骰取最大值。","icons/magic/lightning/bolt-beam-strike-blue.webp"); return `已挂载提醒：额外动作 + 移动动作（由你执行）；下一发法术取最大值（由 DM 裁定）。 ${pollute("")}`; }
      if(o.n===5){ const roll=await (new Roll("2d6")).evaluate(); await actor.applyDamage([{value:roll.total,type:"necrotic"}]); return `已承受 ${roll.total} 点暗蚀反噬。 ${pollute("")}`; }
    }
    // ===== 安慰奖 =====
    if(o.kind==='consol'){
      if(o.n===0){ if(typeof actor.applyTempHP==="function"){ await actor.applyTempHP(5); return "已获得 5 点临时生命值。"; } return "请手动获得 5 点临时生命值。"; }
      if(o.n===1){ const a=await useAct("奥术飞弹"); return a.ok?"已发动「奥术飞弹」：点选一个目标，对其造成 2d8 力场伤害。":"⚠ 奥术飞弹触发失败，请手动结算。"; }
      if(o.n===2){ await mkEff("守势  Warding",[{key:"system.bonuses.abilities.save",mode:2,value:"2",priority:20}],"你的下一次豁免检定获得 +2 加值。","icons/magic/defensive/shield-barrier-deflect-gold.webp",["isSave"]); return "已挂载：下一次豁免 +2（持续至你下回合）。"; }
