    _whir:null,startWhir(){this.on();if(!this.ctx)return;this.stopWhir();let k=0;const p=[587,440];this._whir=setInterval(()=>{if(this.muted||!this.ctx)return;const f=p[k++%2],t=this.ctx.currentTime+0.01;this.tone(f,t,0.11,'sine',0.17);this.tone(f*2,t,0.08,'sine',0.045);},125);},
    stopWhir(){if(this._whir){clearInterval(this._whir);this._whir=null;}},
    ding(i){this.on();if(!this.ctx)return;const t=this.ctx.currentTime+0.02;const sc=[988,1175,1319,1568,1760,2093];const f=sc[Math.min(i,sc.length-1)];this.tone(f,t,0.3,'sine',0.32);this.tone(f*2,t,0.18,'sine',0.14);this.tone(f*3,t,0.09,'sine',0.05);this.noise(t,0.015,0.1,f*2);},
    fanfare(){this.on();if(!this.ctx)return;const t=this.ctx.currentTime+0.02;[523,659,784,1047].forEach((f,i)=>this.tone(f,t+i*0.09,0.5,'triangle',0.3));this.tone(1568,t+0.36,0.7,'sine',0.18);}
  };

  // ---------- 转盘 / 判定 / 演出 ----------
  const cellH=80,LAND=9,reels=[...root.querySelectorAll(".pv-strip")];
  reels.forEach(s=>s.style.transform=`translateY(${cellH}px)`);
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  function spinOne(strip,target,dur){
    const prev=+strip.dataset.i, fromY=(1-prev)*cellH;
    const fi=LAND*ORDER.length+ORDER.indexOf(target), toY=(1-fi)*cellH;
    strip.style.transform=`translateY(${fromY}px)`;
    const a=strip.animate([{transform:`translateY(${fromY}px)`},{transform:`translateY(${toY}px)`}],{duration:dur,easing:'cubic-bezier(.16,.7,.12,1)',fill:'forwards'});
    strip.dataset.i=ORDER.indexOf(target);
    return a.finished.then(()=>{strip.style.transform=`translateY(${toY}px)`;a.cancel();});
  }
  function winningReels(res3,r){
    if(r.tier==='grand')return[0,1,2];
    if(r.tier==='jackpot'||r.tier==='pair')return res3.map((s,i)=>(s===r.sym)?i:-1).filter(i=>i>=0);
    return [];
  }
  const screen=root.querySelector(".pv-screen"),flash=root.querySelector(".pv-flash"),pop=root.querySelector(".pv-pop"),
        popCard=root.querySelector(".pv-pop-card"),popSyms=root.querySelector(".pv-pop-syms"),popBody=root.querySelector(".pv-pop-body");
  pop.addEventListener('click',()=>cleanupClose());
  async function present(res3,winIdx){let k=0;for(const i of winIdx){const fi=LAND*ORDER.length+ORDER.indexOf(res3[i]);reels[i].children[fi]?.classList.add('pv-lit');SFX.ding(k++);await sleep(280);}if(winIdx.length)await sleep(260);}

  let busy=false, __closed=false;
  function cleanupClose(){ if(__closed)return; __closed=true; try{globalThis.__pvPanelOpen=false;}catch(e){} try{document.getElementById('pv-style')?.remove();}catch(e){} try{dlg.close();}catch(e){} }
  function scheduleClose(big){ setTimeout(cleanupClose, big?5200:3400); }
  async function go(){
    if(busy)return;busy=true;
    pop.classList.remove('pv-show');screen.classList.remove('pv-win');
    reels.forEach(s=>{for(const c of s.children)c.classList.remove('pv-lit');});
    SFX.clunk();setTimeout(()=>SFX.dengSeq(),150);setTimeout(()=>SFX.startWhir(),650);
    const {res3,r}=buildResult();
    const durs=[1800,2300,2800];
    durs.forEach((d,i)=>setTimeout(()=>SFX.deng(740+i*120),d));
    await Promise.all(reels.map((s,i)=>spinOne(s,res3[i],durs[i])));
    SFX.stopWhir();
    const big=(r.tier==='jackpot'||r.tier==='grand'), winIdx=winningReels(res3,r);
    if(winIdx.length)screen.classList.add('pv-win');
    if(big){flash.classList.remove('pv-go');void flash.offsetWidth;flash.classList.add('pv-go');}
    await present(res3,winIdx);
    if(big)SFX.fanfare();
    const o=outcome(r);
    popSyms.textContent=res3.map(s=>NAME[s]).join('  ·  ');
    popBody.textContent=o.text;
    popCard.classList.toggle('pv-jack',big);
    await sleep(big?360:200);pop.classList.add('pv-show');
    scheduleClose(big);
    // ---- 发聊天卡 + 自动派发 ----
    const auto=await autoApply(o);
    const tierName={grand:'★ 777 大头奖 ★',jackpot:'大奖',pair:'小奖',none:'安慰奖'}[r.tier];
    await ChatMessage.create({
      speaker:ChatMessage.getSpeaker({actor}),
      content:`<div style="border:1px solid #6a4a8a;border-radius:8px;padding:8px 10px;background:#1a1226;color:#efe7f7">
        <div style="font-weight:700;color:#ff3ea5">百变腕甲 · ${tierName}</div>
        <div style="font-size:12px;color:#c9bbe0;margin:2px 0 6px">${res3.map(s=>NAME[s]).join(' · ')}</div>
        <div>${o.text}</div>
        ${auto?`<div style="margin-top:6px;font-size:12px;color:#5cff8f">⚙ ${auto}</div>`:''}
      </div>`
    });
    // 本次转动结束：保持锁定（busy=true），面板将自动关闭，避免同一次激活内重复转动
  }

  // ---------- 拉杆拖动 + 兜底点击 ----------
  const lever=root.querySelector(".pv-lever"),knob=lever.querySelector(".pv-knob");
  let drag=false,sy=0,rot=0;const TH=30;
  const setRot=d=>{rot=Math.max(0,Math.min(38,d));lever.style.transform=`rotate(${rot}deg)`;};
  const release=tr=>{drag=false;lever.classList.add('pv-snap');lever.style.transform='rotate(0deg)';setTimeout(()=>lever.classList.remove('pv-snap'),460);if(tr)go();};
  knob.addEventListener('pointerdown',e=>{if(busy)return;e.preventDefault();SFX.on();drag=true;sy=e.clientY;lever.classList.remove('pv-snap');knob.setPointerCapture(e.pointerId);});
  knob.addEventListener('pointermove',e=>{if(!drag)return;setRot((e.clientY-sy)*0.42);if(rot>=36)release(true);});
  knob.addEventListener('pointerup',()=>{if(drag)release(rot>=TH);});
  knob.addEventListener('pointercancel',()=>{if(drag)release(rot>=TH);});
  knob.addEventListener('click',()=>{if(!busy&&rot<2){SFX.on();go();}});
})();
